      await api(`/api/agent-candidate-results/${item.id}/reviews`,{method:"POST",body:JSON.stringify({decision:"rejected",actor:item.project.owner,actor_role:"project_owner",reason})});
      status.textContent="已记录拒绝原因；未创建交付物或版本。";
